import heapq


def shortest_path(edges, start, end):
    """
    Find the shortest path in a directed weighted graph using Dijkstra's algorithm.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node
        end: Ending node

    Returns:
        Tuple (distance, path) where distance is the total weight of the path
        and path is a list of nodes from start to end.
        Returns (0, [start]) if start == end.
        Returns (None, None) if no path exists.
        Raises ValueError if any edge has negative weight.
    """
    # Check for negative weights
    for edge in edges:
        if len(edge) < 3:
            continue
        if edge[2] < 0:
            raise ValueError("Negative edge weight detected")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    # Distance from start to each node
    distances = {start: 0}
    # Previous node for path reconstruction
    previous = {start: None}
    # Priority queue: (distance, node)
    pq = [(0, start)]
    # Visited set
    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        if node == end:
            break

        for neighbor, weight in graph.get(node, []):
            if neighbor in visited:
                continue
            new_dist = dist + weight
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                previous[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    if end not in distances:
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous.get(current)
    path.reverse()

    # Verify the path is valid
    if path[0] != start or path[-1] != end:
        return (None, None)

    return (distances[end], path)
